#include "stdafx.h"#include "HcdElementBase.h"struct SUPDN_P{#include "PrivateVars/UPDN.h"};class KUPDN : public KHcdElementBase  , protected SUPDN_P{public:  static IHcdElement *Create();protected:  static void InitParm();  virtual void OnCreated( int domain, LPCSTR pszHmiTagName );  virtual void StepCalc( SStepCalcParams &params );};static KHcdFactory _UPDN("UPDN", KUPDN::Create);IHcdElement *KUPDN::Create(){  return new KUPDN;}//////////////////////////////////////////////////////////////////////////#include "_InitInfo.h"DECLARE_PRIVATE_VARSINFO( KUPDN, 10 )void KUPDN::InitParm(){#include "PrivateVars/UPDN.h"  qsort( s_privateVarInfo, s_kprivateVarInfo, sizeof( SVarInfo ), CompVarInfo );}void KUPDN::OnCreated( int domain, LPCSTR pszHmiTagName ){  if( !s_kprivateVarInfo )    InitParm();  m_kPrivateVarsInfo = s_kprivateVarInfo;  m_pPrivateVarsInfo = s_privateVarInfo;  m_pPrivateObject = (BYTE*)this;}void KUPDN::StepCalc( SStepCalcParams &params ){  if( RST )  {    if( !CNTDN )      OUT = 0;    else      OUT = RemotePreset ? RPRE : LocalPreset;    PREI = 0;    return;  }  if( !prevX && X && !PREI )  {    if( !CNTDN )    {      OUT++;      if( OUT >= (RemotePreset ? RPRE : LocalPreset) )        PREI = 1;    }    else    {      OUT--;      if( !OUT )        PREI = 1;    }  }  prevX = X;}